// Simple register allocator using graph coloring
typedef struct {
    int var_id;
    Set neighbors;  // interfering variables
    int color;      // assigned register, -1 if spilled
} Node;

bool try_color(Graph* g, int num_regs) {
    if (g->num_nodes == 0) return true;

    // Find node with degree < num_regs
    Node* n = find_low_degree_node(g, num_regs);
    if (!n) {
        // Must spill - pick node with highest degree
        n = find_max_degree_node(g);
        n->color = SPILL;
        remove_node(g, n);
    } else {
        remove_node(g, n);
        if (try_color(g, num_regs)) {
            // Assign lowest available color
            n->color = find_free_color(n, num_regs);
            return n->color >= 0;
        }
    }
    return false;
}
